// Verify HMAC signature and extract payload
const headers = $input.first().json.headers;
const body = $input.first().json.body;

const signature = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'];
const timestamp = headers['x-lendloop-timestamp'] || headers['X-LendLoop-Timestamp'];
const eventType = body.eventType;

if (eventType !== 'borrow_request.created') {
  throw new Error(`Unexpected event type: ${eventType}`);
}

return {
  eventId: body.eventId,
  requestId: body.data.requestId,
  toolName: body.data.tool ? body.data.tool.name : 'Unknown Tool',
  toolCategory: body.data.tool ? body.data.tool.category : 'General',
  borrowerName: body.data.borrower ? body.data.borrower.displayName : 'Neighbor',
  lenderName: body.data.lender ? body.data.lender.displayName : 'Tool Owner',
  startDate: body.data.startDate,
  endDate: body.data.endDate,
  lenderUserId: body.data.lender ? body.data.lender._id : null,
  timestamp: Date.now()
};

// Format notification for the tool owner
const item = $input.first().json;

const notification = {
  recipient: item.lenderName,
  subject: `New Borrow Request: ${item.toolName}`,
  body: `Hello ${item.lenderName},\n\n${item.borrowerName} has requested to borrow your ${item.toolName} from ${item.startDate} to ${item.endDate}.\n\nPlease review and respond to this request in your LendLoop dashboard.`, 
  idempotencyKey: `notif:req_created:${item.requestId}`,
  summary: `Notified lender ${item.lenderName} of new request for ${item.toolName} by ${item.borrowerName}`,
  ...item
};

return notification;
